impl CascadeExpression {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        return ast.begin_token(self.target);
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        if let Some(result) = ast.list_end_token(self.cascade_sections) {
            return result;
        }
        return ast.end_token(self.target);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        out.push(Entity::Node(self.target.raw()));
        out.extend(
            ast.list_raw(self.cascade_sections)
                .iter()
                .map(|&c| Entity::Node(c)),
        );
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        f(self.target.raw());
        for &c in ast.list_raw(self.cascade_sections) {
            f(c);
        }
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if ast.contains_offset(self.target, start, end) {
            return Some(self.target.raw());
        }
        if let Some(result) = ast.element_containing_range(self.cascade_sections, start, end) {
            return Some(result);
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.target.raw() == old {
            assert!(
                <Expression as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Expression"
            );
            self.target = crate::arena::Id::from_raw(new);
            return true;
        }
        if let Some(slot) = self
            .cascade_sections
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <Expression as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Expression"
            );
            *slot = new;
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.target.raw() == old {
            return Err("Cannot remove required child 'target'.".into());
        }
        if self.cascade_sections.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'cascadeSections' because NodeList cannot be resized.".into(),
            );
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        self.target.raw() == child
    }
}

