impl CatchClause {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        if let Some(on_keyword) = self.on_keyword {
            return on_keyword;
        }
        if let Some(exception_type) = self.exception_type {
            return ast.begin_token(exception_type);
        }
        if let Some(catch_keyword) = self.catch_keyword {
            return catch_keyword;
        }
        if let Some(left_parenthesis) = self.left_parenthesis {
            return left_parenthesis;
        }
        if let Some(exception_parameter) = self.exception_parameter {
            return ast.begin_token(exception_parameter);
        }
        if let Some(comma) = self.comma {
            return comma;
        }
        if let Some(stack_trace_parameter) = self.stack_trace_parameter {
            return ast.begin_token(stack_trace_parameter);
        }
        if let Some(right_parenthesis) = self.right_parenthesis {
            return right_parenthesis;
        }
        return ast.begin_token(self.body);
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return ast.end_token(self.body);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(t) = self.on_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.exception_type {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(t) = self.catch_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.left_parenthesis {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.exception_parameter {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(t) = self.comma {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.stack_trace_parameter {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(t) = self.right_parenthesis {
            out.push(Entity::Token(t));
        }
        out.push(Entity::Node(self.body.raw()));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        if let Some(c) = self.exception_type {
            f(c.raw());
        }
        if let Some(c) = self.exception_parameter {
            f(c.raw());
        }
        if let Some(c) = self.stack_trace_parameter {
            f(c.raw());
        }
        f(self.body.raw());
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if let Some(c) = self.exception_type {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(c) = self.exception_parameter {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(c) = self.stack_trace_parameter {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if ast.contains_offset(self.body, start, end) {
            return Some(self.body.raw());
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.exception_type.map(|c| c.raw()) == Some(old) {
            assert!(
                <TypeAnnotation as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a TypeAnnotation"
            );
            self.exception_type = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.exception_parameter.map(|c| c.raw()) == Some(old) {
            assert!(
                <CatchClauseParameter as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a CatchClauseParameter"
            );
            self.exception_parameter = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.stack_trace_parameter.map(|c| c.raw()) == Some(old) {
            assert!(
                <CatchClauseParameter as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a CatchClauseParameter"
            );
            self.stack_trace_parameter = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.body.raw() == old {
            assert!(
                <Block as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Block"
            );
            self.body = crate::arena::Id::from_raw(new);
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.exception_type.map(|c| c.raw()) == Some(old) {
            self.exception_type = None;
            return Ok(());
        }
        if self.exception_parameter.map(|c| c.raw()) == Some(old) {
            self.exception_parameter = None;
            return Ok(());
        }
        if self.stack_trace_parameter.map(|c| c.raw()) == Some(old) {
            self.stack_trace_parameter = None;
            return Ok(());
        }
        if self.body.raw() == old {
            return Err("Cannot remove required child 'body'.".into());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        false
    }
}

