impl ConstantPattern {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        if let Some(const_keyword) = self.const_keyword {
            return const_keyword;
        }
        return ast.begin_token(self.expression);
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return ast.end_token(self.expression);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(t) = self.const_keyword {
            out.push(Entity::Token(t));
        }
        out.push(Entity::Node(self.expression.raw()));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        f(self.expression.raw());
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if ast.contains_offset(self.expression, start, end) {
            return Some(self.expression.raw());
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.expression.raw() == old {
            assert!(
                <Expression as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Expression"
            );
            self.expression = crate::arena::Id::from_raw(new);
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.expression.raw() == old {
            return Err("Cannot remove required child 'expression'.".into());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        true
    }
}

impl ConstructorDeclaration {
    /// Dart `firstTokenAfterCommentAndMetadata`.
    pub fn first_token_after_comment_and_metadata(&self, ast: &Ast) -> TokenId {
        if let Some(result) = lexically_first(
            &ast.tokens,
            &[
                self.augment_keyword,
                self.external_keyword,
                self.const_keyword,
                self.factory_keyword,
                self.new_keyword,
            ],
        ) {
            return result;
        }
        if let Some(type_name) = self.type_name {
            return ast.begin_token(type_name);
        }
        if let Some(period) = self.period {
            return period;
        }
        if let Some(name) = self.name {
            return name;
        }
        return ast.begin_token(self.parameters);
    }

    /// Dart `beginToken` (`_AnnotatedNodeMixin`).
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        ast.annotated_begin_token(self.documentation_comment, self.metadata)
            .unwrap_or_else(|| self.first_token_after_comment_and_metadata(ast))
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return ast.end_token(self.body);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(c) = self.documentation_comment {
            out.push(Entity::Node(c.raw()));
        }
        out.extend(ast.list_raw(self.metadata).iter().map(|&c| Entity::Node(c)));
        if let Some(t) = self.augment_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.external_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.const_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.factory_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.new_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.type_name {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(t) = self.period {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.name {
            out.push(Entity::Token(t));
        }
        out.push(Entity::Node(self.parameters.raw()));
        if let Some(t) = self.separator {
            out.push(Entity::Token(t));
        }
        out.extend(
            ast.list_raw(self.initializers)
                .iter()
                .map(|&c| Entity::Node(c)),
        );
        if let Some(c) = self.redirected_constructor {
            out.push(Entity::Node(c.raw()));
        }
        out.push(Entity::Node(self.body.raw()));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        ast.visit_comment_and_annotations(self.documentation_comment, self.metadata, f);
        if let Some(c) = self.type_name {
            f(c.raw());
        }
        f(self.parameters.raw());
        for &c in ast.list_raw(self.initializers) {
            f(c);
        }
        if let Some(c) = self.redirected_constructor {
            f(c.raw());
        }
        f(self.body.raw());
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if let Some(c) = self.documentation_comment {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(result) = ast.element_containing_range(self.metadata, start, end) {
            return Some(result);
        }
        if let Some(c) = self.type_name {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if ast.contains_offset(self.parameters, start, end) {
            return Some(self.parameters.raw());
        }
        if let Some(result) = ast.element_containing_range(self.initializers, start, end) {
            return Some(result);
        }
        if let Some(c) = self.redirected_constructor {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if ast.contains_offset(self.body, start, end) {
            return Some(self.body.raw());
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.documentation_comment.map(|c| c.raw()) == Some(old) {
            assert!(
                <Comment as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Comment"
            );
            self.documentation_comment = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if let Some(slot) = self
            .metadata
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <Annotation as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Annotation"
            );
            *slot = new;
            return true;
        }
        if self.type_name.map(|c| c.raw()) == Some(old) {
            assert!(
                <SimpleIdentifier as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a SimpleIdentifier"
            );
            self.type_name = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.parameters.raw() == old {
            assert!(
                <FormalParameterList as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a FormalParameterList"
            );
            self.parameters = crate::arena::Id::from_raw(new);
            return true;
        }
        if let Some(slot) = self
            .initializers
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <ConstructorInitializer as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a ConstructorInitializer"
            );
            *slot = new;
            return true;
        }
        if self.redirected_constructor.map(|c| c.raw()) == Some(old) {
            assert!(
                <ConstructorName as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a ConstructorName"
            );
            self.redirected_constructor = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.body.raw() == old {
            assert!(
                <FunctionBody as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a FunctionBody"
            );
            self.body = crate::arena::Id::from_raw(new);
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.documentation_comment.map(|c| c.raw()) == Some(old) {
            self.documentation_comment = None;
            return Ok(());
        }
        if self.metadata.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'metadata' because NodeList cannot be resized.".into(),
            );
        }
        if self.type_name.map(|c| c.raw()) == Some(old) {
            self.type_name = None;
            return Ok(());
        }
        if self.parameters.raw() == old {
            return Err("Cannot remove required child 'parameters'.".into());
        }
        if self.initializers.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'initializers' because NodeList cannot be resized.".into(),
            );
        }
        if self.redirected_constructor.map(|c| c.raw()) == Some(old) {
            self.redirected_constructor = None;
            return Ok(());
        }
        if self.body.raw() == old {
            return Err("Cannot remove required child 'body'.".into());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        false
    }
}

impl ConstructorFieldInitializer {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        if let Some(this_keyword) = self.this_keyword {
            return this_keyword;
        }
        if let Some(period) = self.period {
            return period;
        }
        return ast.begin_token(self.field_name);
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return ast.end_token(self.expression);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(t) = self.this_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.period {
            out.push(Entity::Token(t));
        }
        out.push(Entity::Node(self.field_name.raw()));
        out.push(Entity::Token(self.equals));
        out.push(Entity::Node(self.expression.raw()));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        f(self.field_name.raw());
        f(self.expression.raw());
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if ast.contains_offset(self.field_name, start, end) {
            return Some(self.field_name.raw());
        }
        if ast.contains_offset(self.expression, start, end) {
            return Some(self.expression.raw());
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.field_name.raw() == old {
            assert!(
                <SimpleIdentifier as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a SimpleIdentifier"
            );
            self.field_name = crate::arena::Id::from_raw(new);
            return true;
        }
        if self.expression.raw() == old {
            assert!(
                <Expression as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Expression"
            );
            self.expression = crate::arena::Id::from_raw(new);
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.field_name.raw() == old {
            return Err("Cannot remove required child 'fieldName'.".into());
        }
        if self.expression.raw() == old {
            return Err("Cannot remove required child 'expression'.".into());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        self.expression.raw() == child
    }
}

impl ConstructorName {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        return ast.begin_token(self.type_);
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        if let Some(name) = self.name {
            return ast.end_token(name);
        }
        if let Some(period) = self.period {
            return period;
        }
        return ast.end_token(self.type_);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        out.push(Entity::Node(self.type_.raw()));
        if let Some(t) = self.period {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.name {
            out.push(Entity::Node(c.raw()));
        }
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        f(self.type_.raw());
        if let Some(c) = self.name {
            f(c.raw());
        }
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if ast.contains_offset(self.type_, start, end) {
            return Some(self.type_.raw());
        }
        if let Some(c) = self.name {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.type_.raw() == old {
            assert!(
                <NamedType as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a NamedType"
            );
            self.type_ = crate::arena::Id::from_raw(new);
            return true;
        }
        if self.name.map(|c| c.raw()) == Some(old) {
            assert!(
                <SimpleIdentifier as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a SimpleIdentifier"
            );
            self.name = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.type_.raw() == old {
            return Err("Cannot remove required child 'type'.".into());
        }
        if self.name.map(|c| c.raw()) == Some(old) {
            self.name = None;
            return Ok(());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        false
    }
}

