impl MethodDeclaration {
    /// Dart `firstTokenAfterCommentAndMetadata`.
    pub fn first_token_after_comment_and_metadata(&self, ast: &Ast) -> TokenId {
        if let Some(augment_keyword) = self.augment_keyword {
            return augment_keyword;
        }
        if let Some(result) =
            lexically_first(&ast.tokens, &[self.external_keyword, self.modifier_keyword])
        {
            return result;
        }
        if let Some(return_type) = self.return_type {
            return ast.begin_token(return_type);
        }
        if let Some(result) =
            lexically_first(&ast.tokens, &[self.property_keyword, self.operator_keyword])
        {
            return result;
        }
        return self.name;
    }

    /// Dart `beginToken` (`_AnnotatedNodeMixin`).
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        ast.annotated_begin_token(self.documentation_comment, self.metadata)
            .unwrap_or_else(|| self.first_token_after_comment_and_metadata(ast))
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return ast.end_token(self.body);
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(c) = self.documentation_comment {
            out.push(Entity::Node(c.raw()));
        }
        out.extend(ast.list_raw(self.metadata).iter().map(|&c| Entity::Node(c)));
        if let Some(t) = self.augment_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.external_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.modifier_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.return_type {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(t) = self.property_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(t) = self.operator_keyword {
            out.push(Entity::Token(t));
        }
        out.push(Entity::Token(self.name));
        if let Some(c) = self.type_parameters {
            out.push(Entity::Node(c.raw()));
        }
        if let Some(c) = self.parameters {
            out.push(Entity::Node(c.raw()));
        }
        out.push(Entity::Node(self.body.raw()));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        ast.visit_comment_and_annotations(self.documentation_comment, self.metadata, f);
        if let Some(c) = self.return_type {
            f(c.raw());
        }
        if let Some(c) = self.type_parameters {
            f(c.raw());
        }
        if let Some(c) = self.parameters {
            f(c.raw());
        }
        f(self.body.raw());
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if let Some(c) = self.documentation_comment {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(result) = ast.element_containing_range(self.metadata, start, end) {
            return Some(result);
        }
        if let Some(c) = self.return_type {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(c) = self.type_parameters {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(c) = self.parameters {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if ast.contains_offset(self.body, start, end) {
            return Some(self.body.raw());
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.documentation_comment.map(|c| c.raw()) == Some(old) {
            assert!(
                <Comment as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Comment"
            );
            self.documentation_comment = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if let Some(slot) = self
            .metadata
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <Annotation as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Annotation"
            );
            *slot = new;
            return true;
        }
        if self.return_type.map(|c| c.raw()) == Some(old) {
            assert!(
                <TypeAnnotation as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a TypeAnnotation"
            );
            self.return_type = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.type_parameters.map(|c| c.raw()) == Some(old) {
            assert!(
                <TypeParameterList as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a TypeParameterList"
            );
            self.type_parameters = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.parameters.map(|c| c.raw()) == Some(old) {
            assert!(
                <FormalParameterList as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a FormalParameterList"
            );
            self.parameters = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if self.body.raw() == old {
            assert!(
                <FunctionBody as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a FunctionBody"
            );
            self.body = crate::arena::Id::from_raw(new);
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.documentation_comment.map(|c| c.raw()) == Some(old) {
            self.documentation_comment = None;
            return Ok(());
        }
        if self.metadata.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'metadata' because NodeList cannot be resized.".into(),
            );
        }
        if self.return_type.map(|c| c.raw()) == Some(old) {
            self.return_type = None;
            return Ok(());
        }
        if self.type_parameters.map(|c| c.raw()) == Some(old) {
            self.type_parameters = None;
            return Ok(());
        }
        if self.parameters.map(|c| c.raw()) == Some(old) {
            self.parameters = None;
            return Ok(());
        }
        if self.body.raw() == old {
            return Err("Cannot remove required child 'body'.".into());
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        false
    }
}

