impl SetOrMapLiteral {
    /// Dart `beginToken`.
    pub fn begin_token(&self, ast: &Ast) -> TokenId {
        if let Some(const_keyword) = self.const_keyword {
            return const_keyword;
        }
        if let Some(type_arguments) = self.type_arguments {
            return ast.begin_token(type_arguments);
        }
        return self.left_bracket;
    }

    /// Dart `endToken`.
    pub fn end_token(&self, ast: &Ast) -> TokenId {
        return self.right_bracket;
    }

    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        if let Some(t) = self.const_keyword {
            out.push(Entity::Token(t));
        }
        if let Some(c) = self.type_arguments {
            out.push(Entity::Node(c.raw()));
        }
        out.push(Entity::Token(self.left_bracket));
        out.extend(ast.list_raw(self.elements).iter().map(|&c| Entity::Node(c)));
        out.push(Entity::Token(self.right_bracket));
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        if let Some(c) = self.type_arguments {
            f(c.raw());
        }
        for &c in ast.list_raw(self.elements) {
            f(c);
        }
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if let Some(c) = self.type_arguments {
            if ast.contains_offset(c, start, end) {
                return Some(c.raw());
            }
        }
        if let Some(result) = ast.element_containing_range(self.elements, start, end) {
            return Some(result);
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if self.type_arguments.map(|c| c.raw()) == Some(old) {
            assert!(
                <TypeArgumentList as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a TypeArgumentList"
            );
            self.type_arguments = Some(crate::arena::Id::from_raw(new));
            return true;
        }
        if let Some(slot) = self
            .elements
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <CollectionElement as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a CollectionElement"
            );
            *slot = new;
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.type_arguments.map(|c| c.raw()) == Some(old) {
            self.type_arguments = None;
            return Ok(());
        }
        if self.elements.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'elements' because NodeList cannot be resized.".into(),
            );
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        self.type_arguments.map(|c| c.raw()) != Some(child)
    }
}

