    /// Dart `_childEntities` (in property order, not sorted).
    pub(crate) fn child_entities_unsorted(&self, ast: &Ast, out: &mut Vec<Entity>) {
        out.extend(ast.list_raw(self.labels).iter().map(|&c| Entity::Node(c)));
        out.push(Entity::Token(self.keyword));
        out.push(Entity::Node(self.expression.raw()));
        out.push(Entity::Token(self.colon));
        out.extend(
            ast.list_raw(self.statements)
                .iter()
                .map(|&c| Entity::Node(c)),
        );
    }

    /// The child nodes in Dart `visitChildren` order.
    pub(crate) fn for_each_child(&self, ast: &Ast, f: &mut dyn FnMut(NodeId)) {
        for &c in ast.list_raw(self.labels) {
            f(c);
        }
        f(self.expression.raw());
        for &c in ast.list_raw(self.statements) {
            f(c);
        }
    }

    /// Dart `_childContainingRange`: the child that contains the range.
    pub(crate) fn child_containing_range(&self, ast: &Ast, start: u32, end: u32) -> Option<NodeId> {
        if let Some(result) = ast.element_containing_range(self.labels, start, end) {
            return Some(result);
        }
        if ast.contains_offset(self.expression, start, end) {
            return Some(self.expression.raw());
        }
        if let Some(result) = ast.element_containing_range(self.statements, start, end) {
            return Some(result);
        }
        None
    }

    /// Dart `replaceChild`: replaces [old] with [new] (of kind [kind]) in
    /// a child slot. Returns false if [old] is not a child.
    pub(crate) fn replace_child(
        &mut self,
        lists: &mut [NodeId],
        old: NodeId,
        new: NodeId,
        kind: NodeKind,
    ) -> bool {
        if let Some(slot) = self.labels.slots_mut(lists).iter_mut().find(|c| **c == old) {
            assert!(
                <Label as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Label"
            );
            *slot = new;
            return true;
        }
        if self.expression.raw() == old {
            assert!(
                <Expression as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Expression"
            );
            self.expression = crate::arena::Id::from_raw(new);
            return true;
        }
        if let Some(slot) = self
            .statements
            .slots_mut(lists)
            .iter_mut()
            .find(|c| **c == old)
        {
            assert!(
                <Statement as NodeType>::test(kind),
                "replaceChild: {kind:?} is not a Statement"
            );
            *slot = new;
            return true;
        }
        false
    }

    /// Dart `removeChild`: clears a nullable child slot that holds [old].
    pub(crate) fn remove_child(&mut self, lists: &[NodeId], old: NodeId) -> Result<(), String> {
        if self.labels.slots(lists).contains(&old) {
            return Err("Cannot remove child 'labels' because NodeList cannot be resized.".into());
        }
        if self.expression.raw() == old {
            return Err("Cannot remove required child 'expression'.".into());
        }
        if self.statements.slots(lists).contains(&old) {
            return Err(
                "Cannot remove child 'statements' because NodeList cannot be resized.".into(),
            );
        }
        Err("The old node is not a child of this node.".into())
    }

    /// Dart `isInValueExpressionSlot`.
    pub fn is_in_value_expression_slot(&self, ast: &Ast, child: NodeId) -> bool {
        self.expression.raw() == child
    }
